#[derive(Debug, Clone)]
pub struct Reclaim {
    pub hotkey: [u8; 32],
    pub node_id: [u8; 16],
    pub miner: Address,
    pub amount: U256,
    pub alpha_coldkey: [u8; 32],
    pub alpha_amount: U256,
    pub deny_timeout: u64,
}

pub struct NodeCollateralInfo {
    pub hotkey: [u8; 32],
    pub node_id: [u8; 16],
    pub miner: Address,
    pub tao_collateral: U256,
    pub alpha_collateral: U256,
}

pub struct ReclaimInfo {
    pub reclaim_request_id: U256,
    pub hotkey: [u8; 32],
    pub node_id: [u8; 16],
    pub miner: Address,
    pub amount: U256,
    pub alpha_coldkey: [u8; 32],
    pub alpha_amount: U256,
    pub deny_timeout: u64,
}

impl
    From<(
        FixedBytes<32>,
        FixedBytes<16>,
        Address,
        U256,
        FixedBytes<32>,
        U256,
        u64,
    )> for Reclaim
{
    fn from(
        tuple: (
            FixedBytes<32>,
            FixedBytes<16>,
            Address,
            U256,
            FixedBytes<32>,
            U256,
            u64,
        ),
    ) -> Self {
        Self {
            hotkey: {
                let mut hk = [0u8; 32];
                hk.copy_from_slice(tuple.0.as_slice());
                hk
            },
            node_id: {
                let mut b = [0u8; 16];
                b.copy_from_slice(tuple.1.as_slice());
                b
            },
            miner: tuple.2,
            amount: tuple.3,
            alpha_coldkey: {
                let mut ck = [0u8; 32];
                ck.copy_from_slice(tuple.4.as_slice());
                ck
            },
            alpha_amount: tuple.5,
            deny_timeout: tuple.6,
        }
    }
}

// get the collateral contract instance with custom network config
pub async fn get_collateral(
    private_key: &str,
    network_config: &CollateralNetworkConfig,
) -> Result<
    CollateralUpgradeable::CollateralUpgradeableInstance<impl alloy_provider::Provider>,
    anyhow::Error,
> {
    let mut signer: PrivateKeySigner = private_key.parse()?;
    signer.set_chain_id(Some(network_config.chain_id));

    let provider = ProviderBuilder::new()
        .wallet(signer)
        .connect(&network_config.rpc_url)
        .await?;

    let proxied = CollateralUpgradeable::new(network_config.contract_address, provider);

    Ok(proxied)
}

// transactions
pub async fn deposit(
    private_key: &str,
    hotkey: [u8; 32],
    node_id: [u8; 16],
    alpha_hotkey: [u8; 32],
    alpha_amount: U256,
    network_config: &CollateralNetworkConfig,
) -> Result<(), anyhow::Error> {
    let contract = get_collateral(private_key, network_config).await?;

    // Product policy: tx surface is alpha-primary. We intentionally do not send TAO msg.value.
    let tx = contract
        .deposit(
            FixedBytes::from_slice(&hotkey),
            FixedBytes::from_slice(&node_id),
            FixedBytes::from_slice(&alpha_hotkey),
            alpha_amount,
        )
        .value(U256::ZERO);
    let tx = tx.send().await?;
    let receipt = tx.get_receipt().await?;
    tracing::info!("{receipt:?}");
    Ok(())
}

