pub async fn slash_collateral(
    private_key: &str,
    hotkey: [u8; 32],
    node_id: [u8; 16],
    slash_alpha_amount: U256,
    url: &str,
    url_content_sha256: [u8; 32],
    network_config: &CollateralNetworkConfig,
) -> Result<(), anyhow::Error> {
    let contract = get_collateral(private_key, network_config).await?;

    // Product policy: slash operations only target alpha via this client path.
    let tx = contract.slashCollateral(
        FixedBytes::from_slice(&hotkey),
        FixedBytes::from_slice(&node_id),
        U256::ZERO,
        slash_alpha_amount,
        url.to_string(),
        FixedBytes::from_slice(&url_content_sha256),
    );
    let tx = tx.send().await?;
    tx.get_receipt().await?;
    Ok(())
}

