pub async fn collaterals(
    hotkey: [u8; 32],
    node_id: [u8; 16],
    network_config: &CollateralNetworkConfig,
) -> Result<(U256, U256), anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let contract = CollateralUpgradeable::new(network_config.contract_address, provider);
    let hotkey = FixedBytes::from_slice(&hotkey);
    let node_id = FixedBytes::from_slice(&node_id);
    let tao = contract.taoCollaterals(hotkey, node_id).call().await?;
    let alpha = contract.alphaCollaterals(hotkey, node_id).call().await?;
    Ok((tao, alpha))
}

pub async fn collaterals_at_block(
    hotkey: [u8; 32],
    node_id: [u8; 16],
    block_number: u64,
    network_config: &CollateralNetworkConfig,
) -> Result<(U256, U256), anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let contract = CollateralUpgradeable::new(network_config.contract_address, provider);
    let hotkey = FixedBytes::from_slice(&hotkey);
    let node_id = FixedBytes::from_slice(&node_id);
    let block_id = alloy::eips::BlockId::number(block_number);
    let tao = contract
        .taoCollaterals(hotkey, node_id)
        .block(block_id)
        .call()
        .await?;
    let alpha = contract
        .alphaCollaterals(hotkey, node_id)
        .block(alloy::eips::BlockId::number(block_number))
        .call()
        .await?;
    Ok((tao, alpha))
}

pub async fn reclaims(
    reclaim_request_id: U256,
    network_config: &CollateralNetworkConfig,
) -> Result<Reclaim, anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let contract = CollateralUpgradeable::new(network_config.contract_address, provider);
    let result = contract.reclaims(reclaim_request_id).call().await?;
    let reclaim = Reclaim::from((
        result.hotkey,
        result.nodeId,
        result.miner,
        result.amount,
        result.alphaColdkey,
        result.alphaAmount,
        result.denyTimeout,
    ));
    Ok(reclaim)
}

pub async fn get_finalized_block_number(
    network_config: &CollateralNetworkConfig,
) -> Result<u64, anyhow::Error> {
    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    // Use get_block_number() (eth_blockNumber) instead of fetching the full
    // finalized block, because some devnets (e.g. Anvil) return blocks missing
    // optional header fields like `mixHash` which breaks alloy deserialization.
    let block_number = provider.get_block_number().await?;
    Ok(block_number)
}

pub async fn get_all_collaterals_at_block(
    network_config: &CollateralNetworkConfig,
    block_number: u64,
    page_size: u64,
) -> Result<Vec<NodeCollateralInfo>, anyhow::Error> {
    if page_size == 0 {
        return Err(anyhow::anyhow!("page_size must be > 0"));
    }

    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let contract = CollateralUpgradeable::new(network_config.contract_address, provider);

    let total = contract
        .getActiveNodeCount()
        .block(alloy::eips::BlockId::number(block_number))
        .call()
        .await?;
    let mut offset = U256::ZERO;
    let limit = U256::from(page_size);
    let mut nodes = Vec::new();

    while offset < total {
        let page = contract
            .getAllCollaterals(offset, limit)
            .block(alloy::eips::BlockId::number(block_number))
            .call()
            .await?;

        let fetched_len = page.len();
        if fetched_len == 0 {
            return Err(anyhow::anyhow!(
                "received empty collateral page before completion (offset={}, total={}, block={})",
                offset,
                total,
                block_number
            ));
        }

        nodes.extend(page.into_iter().map(|n| NodeCollateralInfo {
            hotkey: n.hotkey.into(),
            node_id: n.nodeId.into(),
            miner: n.miner,
            tao_collateral: n.taoCollateral,
            alpha_collateral: n.alphaCollateral,
        }));

        let fetched = U256::from(
            u64::try_from(fetched_len)
                .map_err(|_| anyhow::anyhow!("collateral page length exceeds u64"))?,
        );
        offset += fetched;
    }

    Ok(nodes)
}

pub async fn get_all_collaterals(
    network_config: &CollateralNetworkConfig,
) -> Result<Vec<NodeCollateralInfo>, anyhow::Error> {
    let block_number = get_finalized_block_number(network_config).await?;
    get_all_collaterals_at_block(network_config, block_number, DEFAULT_SNAPSHOT_PAGE_SIZE).await
}

pub async fn get_all_reclaims_at_block(
    network_config: &CollateralNetworkConfig,
    block_number: u64,
    page_size: u64,
) -> Result<Vec<ReclaimInfo>, anyhow::Error> {
    if page_size == 0 {
        return Err(anyhow::anyhow!("page_size must be > 0"));
    }

    let provider = ProviderBuilder::new()
        .connect(&network_config.rpc_url)
        .await?;
    let contract = CollateralUpgradeable::new(network_config.contract_address, provider);

    let total = contract
        .getActiveReclaimCount()
        .block(alloy::eips::BlockId::number(block_number))
        .call()
        .await?;
    let mut offset = U256::ZERO;
    let limit = U256::from(page_size);
    let mut reclaims = Vec::new();

    while offset < total {
        let page = contract
            .getAllReclaims(offset, limit)
            .block(alloy::eips::BlockId::number(block_number))
            .call()
            .await?;

        let fetched_len = page.len();
        if fetched_len == 0 {
            return Err(anyhow::anyhow!(
                "received empty reclaim page before completion (offset={}, total={}, block={})",
                offset,
                total,
                block_number
            ));
        }

        reclaims.extend(page.into_iter().map(|r| ReclaimInfo {
            reclaim_request_id: r.reclaimRequestId,
            hotkey: r.hotkey.into(),
            node_id: r.nodeId.into(),
            miner: r.miner,
            amount: r.amount,
            alpha_coldkey: r.alphaColdkey.into(),
            alpha_amount: r.alphaAmount,
            deny_timeout: r.denyTimeout,
        }));

        let fetched = U256::from(
            u64::try_from(fetched_len)
                .map_err(|_| anyhow::anyhow!("reclaim page length exceeds u64"))?,
        );
        offset += fetched;
    }

    Ok(reclaims)
}

pub async fn get_all_reclaims(
    network_config: &CollateralNetworkConfig,
) -> Result<Vec<ReclaimInfo>, anyhow::Error> {
    let block_number = get_finalized_block_number(network_config).await?;
    get_all_reclaims_at_block(network_config, block_number, DEFAULT_SNAPSHOT_PAGE_SIZE).await
}

